  "PDF ↔ Word, PowerPoint → PDF, photos → PDF, scanned paper → editable Word, Excel ↔ CSV ↔ JSON, e-books, web pages, subtitles, merge and split PDFs — on your phone. Your files are never uploaded to a converter website.": "PDF ↔ Word, PowerPoint → PDF, foto → PDF, kertas hasil pindai → Word yang bisa diedit, Excel ↔ CSV ↔ JSON, e-book, halaman web, subtitle, gabung dan pisah PDF — di ponselmu. Filemu tidak pernah diunggah ke situs pengubah.",
