  "All conversions": "Semua konversi",
  "Any language, on this phone. Numbers, names and codes can't be changed; every part is checked, and anything doubtful is marked.": "Bahasa apa saja, di ponsel ini. Angka, nama, dan kode tidak bisa berubah; setiap bagian dicek, dan yang meragukan ditandai.",
