  "Every part is checked: numbers, names and codes kept exactly.": "Setiap bagian dicek: angka, nama, dan kode tetap persis.",
  "Open a PDF, Word file, book or web page. Read it here and chat with it — every answer shows the page it came from. Everything stays on your phone.": "Buka PDF, file Word, buku, atau halaman web. Baca di sini dan mengobrol dengannya — setiap jawaban menunjukkan halaman asalnya. Semuanya tetap di ponselmu.",
  "Open a file": "Buka file",
  "Reading and searching work now. To chat with the file, install a model in Engine.": "Membaca dan mencari sudah bisa. Untuk mengobrol dengan file, pasang model di Mesin.",
  "Your documents appear here": "Dokumenmu muncul di sini",
  "Open a file: it is kept on this device, with its chat and notes, so you can come back to it.": "Buka file: file disimpan di perangkat ini, bersama obrolan dan catatannya, jadi kamu bisa kembali lagi.",
  "Stop": "Berhenti",
  "Describe it in one sentence — the AI on your phone writes a designed PowerPoint or a full report, from the web or your own file. Edit any slide, then save it as PowerPoint, Word or PDF.": "Jelaskan dalam satu kalimat — AI di ponselmu menulis PowerPoint yang rapi atau laporan lengkap, dari web atau filemu sendiri. Edit slide mana saja, lalu simpan sebagai PowerPoint, Word, atau PDF.",
  "Presentation": "Presentasi",
  "Report": "Laporan",
  "e.g. A pitch for our café to offices in New Cairo: menu, catering, prices, why us": "mis. Presentasi kafe kami untuk kantor-kantor di New Cairo: menu, katering, harga, kenapa kami",
  "Research the web for facts and figures": "Cari fakta dan angka di web",
  "Each slide names its sources, and a Sources slide lists every page": "Setiap slide menyebut sumbernya, dan slide Sumber mencantumkan semua halaman",
  "Base it on my file (Word, PDF, Excel, CSV…)": "Berdasarkan fileku (Word, PDF, Excel, CSV…)",
