  "Your slides appear here": "Slide-mu muncul di sini",
  "Each slide or section shows here as it is written.": "Setiap slide atau bagian muncul di sini saat ditulis.",
  "Build a CV in English or Arabic, keep a copy for every job, and export a clean PDF or Word file. The AI on your phone helps with wording.": "Buat CV dalam bahasa Inggris atau Arab, simpan salinan untuk setiap lamaran, dan ekspor ke PDF atau Word yang rapi. AI di ponselmu membantu merangkai kata.",
  "New CV": "CV baru",
  "Import my CV": "Impor CV-ku",
  "No CVs yet": "Belum ada CV",
  "Start a new one, or import the one you already have.": "Mulai yang baru, atau impor CV yang sudah kamu punya.",
  "Copy a video's link, paste it here, pick the quality — it's saved to your phone's Movies folder. Works with direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons and pages that show a plain video.": "Salin tautan video, tempel di sini, pilih kualitasnya — video disimpan di folder Movies ponselmu. Bisa untuk tautan video langsung, Google Drive, Dropbox, archive.org, Wikimedia Commons, dan halaman yang menampilkan video biasa.",
  "Find the video": "Cari videonya",
  "The video's versions appear here": "Versi videonya muncul di sini",
  "Paste a link and tap Find the video — then pick the quality to download.": "Tempel tautan dan ketuk Cari videonya — lalu pilih kualitas untuk diunduh.",
  "No map on this device yet": "Belum ada peta di perangkat ini",
  "Download the world map to see every country, or your country's map for streets, places and offline search.": "Unduh peta dunia untuk melihat semua negara, atau peta negaramu untuk jalan, tempat, dan pencarian offline.",
