  "The model writes the program and its tests, the phone runs them, and any error goes straight back to the model to fix — until the tests pass. Offline, in a locked sandbox.": "Model menulis program dan tesnya, ponsel menjalankannya, dan setiap error langsung dikembalikan ke model untuk diperbaiki — sampai tesnya lulus. Offline, di sandbox yang terkunci.",
  "What should it do? e.g. “A function that splits a restaurant bill between friends, with the tip”": "Harus melakukan apa? mis. “Fungsi yang membagi tagihan restoran di antara teman, termasuk tip”",
