  "= instant filler removal (offline).": "= buang kata pengisi secara instan (offline).",
  "= the model rewrites it far shorter while keeping the meaning.": "= model menulis ulang jauh lebih pendek tanpa mengubah makna.",
  "Result": "Hasil",
  "Paste a wordy prompt and hit": "Tempel prompt yang bertele-tele dan tekan",
  "— it thinks about meaning, not just filler words.": "— ia memikirkan makna, bukan sekadar kata pengisi.",
  "Text to rewrite": "Teks untuk ditulis ulang",
  "Paste AI-generated or stiff text — it comes back sounding like a person wrote it.": "Tempel teks buatan AI atau yang kaku — hasilnya terdengar seperti ditulis manusia.",
  "Your writing sample": "Contoh tulisanmu",
  "(this is what makes it sound like you)": "(inilah yang membuatnya terdengar seperti kamu)",
  "Paste a few paragraphs you wrote yourself — an email, a message, anything in your natural voice.": "Tempel beberapa paragraf tulisanmu sendiri — email, pesan, apa saja dengan gaya alamimu.",
  "Keeps your meaning and facts exactly — changes only how it reads. The writing sample is optional but makes the biggest difference.": "Makna dan faktamu tetap persis — hanya cara bacanya yang berubah. Contoh tulisan opsional, tapi paling berpengaruh.",
  "Rewritten": "Hasil tulis ulang",
  "Paste stiff or AI-sounding text, add a sample of your own writing, and it comes back in your voice — same meaning, human rhythm.": "Tempel teks yang kaku atau terdengar seperti AI, tambahkan contoh tulisanmu, dan hasilnya kembali dengan gayamu — makna sama, ritme manusia.",
  "Chat through Attune — it reads the whole conversation and sharpens every next prompt.": "Mengobrol lewat Attune — ia membaca seluruh percakapan dan mempertajam setiap prompt berikutnya.",
  "What do you want out of this whole conversation? (optional, but it makes every prompt better)": "Apa yang kamu mau dari seluruh percakapan ini? (opsional, tapi membuat setiap prompt lebih baik)",
  "Bring the chat from {t} — paste the whole conversation or just its last reply:": "Bawa obrolan dari {t} — tempel seluruh percakapan atau balasan terakhirnya saja:",
  "Paste here…": "Tempel di sini…",
  "Read it & suggest my reply": "Baca & sarankan balasanku",
  "What do you want to ask? Type it however you like.": "Mau tanya apa? Ketik sesukamu.",
  "Optimize my prompt": "Optimalkan prompt-ku",
  "The loop: type intent → get an optimized prompt → send it → bring the reply back → each next prompt is sharper. In the phone app, the share-sheet replaces copy-paste entirely.": "Alurnya: ketik maksud → dapat prompt yang dioptimalkan → kirim → bawa balasannya kembali → setiap prompt berikutnya makin tajam. Di aplikasi ponsel, menu bagikan menggantikan salin-tempel sepenuhnya.",
  "Ready prompt recipes — pick one, fill the blanks, then": "Resep prompt siap pakai — pilih satu, isi bagian kosongnya, lalu",
  "to tailor it.": "untuk menyesuaikannya.",
