  "Messy notes → finished text": "Catatan berantakan → teks jadi",
  "Structure-to-prose is a well-suited LLM task": "Mengubah struktur jadi tulisan adalah tugas yang cocok untuk LLM",
  "Recipes ship with the app and work offline.": "Resep sudah termasuk di aplikasi dan bisa offline.",
  "Ask it anything.": "Tanyakan apa saja.",
  "It answers from this device, and it can look through everything you've asked it before — so questions about your own work have real answers, not guesses.": "Jawabannya dari perangkat ini, dan ia bisa melihat semua yang pernah kamu tanyakan — jadi pertanyaan soal pekerjaanmu sendiri dapat jawaban nyata, bukan tebakan.",
  "What did I ask about last week?": "Aku tanya apa minggu lalu?",
