  "Shop in your pocket": "Toko di saku",
  "Say what your shop is — the counter with barcodes, stock, customers who owe, staff and the end-of-day close, ready in a minute. Every sale goes into your books.": "Sebutkan tokomu jenis apa — kasir dengan barcode, stok, pelanggan yang berutang, karyawan, dan tutup buku harian, siap dalam semenit. Setiap penjualan masuk ke pembukuanmu.",
  "Start a new system": "Mulai sistem baru",
