  "Invoices with VAT, payments and overdue tracking, stock and purchasing, reports — your own accounting, on your phone, in English and Arabic.": "Faktur dengan PPN, pembayaran dan pelacakan jatuh tempo, stok dan pembelian, laporan — akuntansimu sendiri, di ponselmu, dalam bahasa Inggris dan Arab.",
  "Your systems": "Sistemmu",
