  "Build your own business system": "Bangun sistem bisnismu sendiri",
  "For your company, on your phone — no code, and it works without internet.": "Untuk perusahaanmu, di ponselmu — tanpa kode, dan bisa tanpa internet.",
  "Got it": "Mengerti",
