  "One download, then it works offline forever. On Wi-Fi this takes a few minutes; the model stays on your device.": "Sekali unduh, lalu bisa offline selamanya. Lewat Wi-Fi ini butuh beberapa menit; modelnya tetap di perangkatmu.",
