  "Too heavy for a phone — it can close the app. Core or Blaze run smoothly here; this one is in the desktop app.": "Terlalu berat untuk ponsel — aplikasi bisa tertutup. Core atau Blaze jalan lancar di sini; yang ini ada di aplikasi desktop.",
