  "Pro is bought in the Google Play version of Attune — one tap, paid by card or from your Vodafone / Orange / Etisalat balance, and it switches on by itself.": "Pro dibeli di versi Attune dari Google Play — sekali ketuk, bayar dengan kartu atau pulsa Vodafone / Orange / Etisalat, dan langsung aktif sendiri.",
  "Cancel any time in Google Play → Subscriptions. The plan renews by itself; nothing to send, nobody to message.": "Batalkan kapan saja di Google Play → Langganan. Paket diperpanjang otomatis; tidak perlu mengirim apa pun atau menghubungi siapa pun.",
