  "Free: keep and search everything. Pro: it files each item by itself (title, summary, tags), reads your photos and answers questions from your Mind.": "Gratis: simpan dan cari apa saja. Pro: setiap item dirapikan otomatis (judul, ringkasan, tag), foto Anda dibaca, dan pertanyaan dijawab dari Pikiran Anda.",
