  "Nothing to read in that.": "Tidak ada yang bisa dibaca di situ.",
  "That payment did not go through, so there is nothing to record.": "Pembayaran itu tidak berhasil, jadi tidak ada yang perlu dicatat.",
  "Sent to Yusr — pick the account and confirm": "Dikirim ke Yusr — pilih akun dan konfirmasi",
  "Money isn't bundled in this build.": "Fitur Uang tidak disertakan dalam versi ini.",
  "The Yusr document wasn't embedded. On the phone it loads from local assets.": "Dokumen Yusr tidak disematkan. Di ponsel, dokumen dimuat dari file aplikasi.",
  "Your ledger and every zakāt ruling live here, unchanged, and free forever. Attune adds memory and plain language on top — it never calculates zakāt and never moves money on its own.": "Buku kas Anda dan semua ketentuan zakat ada di sini, tanpa diubah, dan gratis selamanya. Attune menambahkan ingatan dan bahasa sederhana di atasnya — tidak pernah menghitung zakat dan tidak pernah memindahkan uang sendiri.",
  "Share a payment": "Bagikan pembayaran",
  "An InstaPay confirmation, a bank SMS, a wallet receipt or a photo of one. Attune reads the amount and who it was, then opens your own transaction sheet with it filled in. You pick the account.": "Konfirmasi InstaPay, SMS bank, struk dompet digital, atau fotonya. Attune membaca jumlah dan penerimanya, lalu membuka lembar transaksi Anda dengan isian yang sudah terisi. Anda yang memilih akunnya.",
  "تم تحويل مبلغ 1,500.00 جنيه إلى AHMED MOHAMED. رقم العملية 987654321": "تم تحويل مبلغ 1,500.00 جنيه إلى AHMED MOHAMED. رقم العملية 987654321",
  "Read it": "Baca",
  "Reading…": "Membaca…",
  "From a photo": "Dari foto",
  "Three ways, all fine: share the SMS, WhatsApp message or screenshot to Attune from any app (it lands here by itself) · paste it above · or take/pick a photo of the receipt.": "Tiga cara, semuanya bisa: bagikan SMS, pesan WhatsApp, atau tangkapan layar ke Attune dari aplikasi mana pun (otomatis masuk ke sini) · tempel di atas · atau ambil/pilih foto struknya.",
  "read from: “": "dibaca dari: “",
  "· account: you choose, in Yusr": "· akun: Anda yang pilih, di Yusr",
  "Talk to your money": "Bicara dengan uang Anda",
  "not saved to memory": "tidak disimpan ke ingatan",
  "saved to memory": "disimpan ke ingatan",
  "Answered on this device from the figures Yusr calculated. Ask follow-ups — it keeps the thread. For zakāt it is handed the app's own numbers and forbidden from recomputing them: it explains, it does not rule.": "Dijawab di perangkat ini dari angka yang dihitung Yusr. Ajukan pertanyaan lanjutan — percakapannya diingat. Untuk zakat, ia diberi angka dari aplikasi dan dilarang menghitung ulang: ia menjelaskan, bukan memberi hukum.",
  "figures from Yusr's zakāt engine, not recalculated": "angka dari mesin zakat Yusr, tidak dihitung ulang",
  "ask a follow-up…": "ajukan pertanyaan lanjutan…",
