  "What do you make of this?": "Bagaimana menurut Anda?",
  "Load a model in Engine and this answers with no signal.": "Muat model di Mesin dan ini bisa menjawab tanpa sinyal.",
  "What stands out": "Yang menonjol",
  "Every figure here is one Yusr calculated — the model may not produce a new number.": "Setiap angka di sini dihitung oleh Yusr — model tidak boleh membuat angka baru.",
  "What the AI is allowed to see": "Apa yang boleh dilihat AI",
