  "Added to memory": "Ditambahkan ke ingatan",
  "Only what you confirmed. Attune records nothing on its own.": "Hanya yang Anda konfirmasi. Attune tidak mencatat apa pun sendiri.",
  "No signal, so only your saved places are searchable — nothing matched.": "Tidak ada sinyal, jadi hanya tempat tersimpan Anda yang bisa dicari — tidak ada yang cocok.",
