  "Every area you look at is kept, so it works again with no signal. You can also download an area before you travel. Place search needs a connection; your own saved places are searchable without one.": "Setiap area yang Anda lihat disimpan, jadi bisa dibuka lagi tanpa sinyal. Anda juga bisa mengunduh area sebelum bepergian. Pencarian tempat butuh koneksi; tempat tersimpan Anda bisa dicari tanpa koneksi.",
