  "The AI on your phone translates it piece by piece; headings, lists, tables and numbers stay in place. Long files take a few minutes.": "AI di ponsel Anda menerjemahkannya bagian demi bagian; judul, daftar, tabel, dan angka tetap di tempatnya. File panjang butuh beberapa menit.",
