  "It knows how things actually work here — fair prices, common overcharges, what's rude. It will tell you when something needs live data it can't have offline.": "Ia tahu cara kerja yang sebenarnya di sini — harga wajar, akal-akalan harga yang umum, apa yang dianggap tidak sopan. Ia akan memberi tahu saat sesuatu butuh data langsung yang tidak bisa didapat offline.",
