  "How it answers": "Cara menjawab",
  "e.g. I run a small shop in Egypt. Answer in Egyptian Arabic unless I write in English. Give prices in EGP.": "mis. Saya punya toko kecil di Indonesia. Jawab dalam bahasa Indonesia kecuali saya menulis dalam bahasa Inggris. Tulis harga dalam IDR.",
