  "Merge": "Gabungkan",
  "Keep everything on this phone and add the backup's chats, memory, reminders and cycle days. The Money ledger is only taken from the backup if this phone has none.": "Pertahankan semua yang ada di ponsel ini dan tambahkan obrolan, ingatan, pengingat, dan hari siklus dari cadangan. Buku kas Uang hanya diambil dari cadangan jika ponsel ini belum punya.",
  "This phone's {c} chats and {l} ledger entries will be replaced by the backup's. You can undo this once, right after.": "{c} obrolan dan {l} entri buku kas di ponsel ini akan diganti dengan isi cadangan. Anda bisa mengurungkannya sekali, tepat setelahnya.",
