  "Name the outcome; it fills in the path.": "Sebutkan hasilnya; ia yang mengisi jalannya.",
  "Huge window — compress for cost, not for fit.": "Jendela sangat besar — padatkan demi biaya, bukan agar muat.",
  "Direct phrasing; ask for reasoning explicitly.": "Kalimat langsung; minta penalaran secara eksplisit.",
  "Structured reasoning; keep numbered steps.": "Penalaran terstruktur; pertahankan langkah bernomor.",
  "Strong multilingual — keep the source language.": "Kuat di banyak bahasa — pertahankan bahasa sumber.",
  "Concise by nature; over-compressing loses nuance.": "Ringkas secara alami; terlalu dipadatkan akan menghilangkan nuansa.",
  "Open weights; explicit instructions beat implied ones.": "Bobot terbuka; instruksi eksplisit lebih baik daripada yang tersirat.",
  "Long documents are its strength; keep headings.": "Dokumen panjang adalah kekuatannya; pertahankan judul.",
  "Code context competes for the window — trim prose first.": "Konteks kode berebut ruang jendela — pangkas teks prosa dulu.",
  "A search tool — keep the sources, cut the styling.": "Alat pencari — pertahankan sumbernya, buang gayanya.",
  "Tight. Cut everything that isn't the instruction.": "Sempit. Buang semua yang bukan instruksi.",
  "Room for a short history, not a long one.": "Cukup untuk riwayat pendek, bukan yang panjang.",
