  "Qwen3.6 35B-A3B · long context": "Qwen3.6 35B-A3B · konteks panjang",
  "Write": "Menulis",
  "Review": "Tinjau",
  "Long documents": "Dokumen panjang",
  "The strongest dense model that still fits a 32 GB machine. Quantisation-aware trained, so 4-bit costs almost nothing in quality here.": "Model padat terkuat yang masih muat di mesin 32 GB. Dilatih dengan memperhitungkan kuantisasi, jadi 4-bit hampir tidak mengurangi kualitas di sini.",
  "26B-class answers with under 4B active per token. The best quality-per-second on a strong laptop.": "Jawaban kelas 26B dengan kurang dari 4B parameter aktif per token. Kualitas per detik terbaik di laptop yang kuat.",
  "Reads text, images and audio. Comfortable on a laptop or a 16 GB phone.": "Membaca teks, gambar, dan audio. Nyaman di laptop atau ponsel 16 GB.",
  "Photos": "Foto",
  "The strongest sub-10B model measured anywhere, and the best of these at reading documents and photographs.": "Model di bawah 10B terkuat yang pernah diukur, dan yang terbaik di antara ini dalam membaca dokumen dan foto.",
  "The one to have if your phone can hold it. Reads photographs of documents and receipts, handles Arabic and English, and a fifth bit of precision over the smaller build is a real quality difference you can feel on long answers.": "Pilihan utama kalau ponsel Anda muat. Membaca foto dokumen dan struk, menangani bahasa Arab dan Inggris, dan presisi satu bit ekstra dibanding versi lebih kecil memberi beda kualitas nyata yang terasa di jawaban panjang.",
  "Text, images and audio on a flagship phone. Pick this over the Qwen if you want voice notes read back to you.": "Teks, gambar, dan audio di ponsel flagship. Pilih ini daripada Qwen kalau Anda ingin pesan suara dibacakan kembali.",
  "Voice": "Suara",
  "The sweet spot on an ordinary modern phone. Everything the app does, in under 3 GB.": "Pilihan pas untuk ponsel modern biasa. Semua yang dilakukan aplikasi, di bawah 3 GB.",
  "The same 4B model squeezed 10% smaller for a 4 GB phone. Slightly slower on older chips, and worth it to get the 4B rather than dropping to the 2B.": "Model 4B yang sama, dipadatkan 10% lebih kecil untuk ponsel 4 GB. Sedikit lebih lambat di chip lama, tapi sepadan untuk tetap memakai 4B daripada turun ke 2B.",
  "Runs on a cheap phone and still reads photographs. Short answers are good; long reasoning is where you'll notice the size.": "Jalan di ponsel murah dan tetap bisa membaca foto. Jawaban pendeknya bagus; penalaran panjang di situlah ukurannya terasa.",
  "For a phone that can't hold anything else. Useful for tidying and shortening text; don't ask it to reason.": "Untuk ponsel yang tidak muat model lain. Berguna untuk merapikan dan meringkas teks; jangan minta ia bernalar.",
  "This device is below what any local model needs": "Perangkat ini di bawah kebutuhan model lokal mana pun",
  "Everything here runs on your own hardware, and the smallest useful model wants about 2 GB of memory to itself. Attune's tools that don't need a model still work.": "Semua di sini berjalan di perangkat Anda sendiri, dan model berguna terkecil butuh sekitar 2 GB memori untuk dirinya sendiri. Alat Attune yang tidak butuh model tetap berfungsi.",
  "Neural Engine": "Neural Engine",
  "prefill + decode": "prefill + decode",
  "Rewrite": "Tulis ulang",
  "Field docs": "Dokumen lapangan",
  "It declined or dodged the question.": "Ia menolak atau menghindari pertanyaannya.",
  "Say why you need it and what you'll do with it, and ask for the part it can answer.": "Sebutkan kenapa Anda butuh dan untuk apa, lalu minta bagian yang bisa dijawabnya.",
  "It hedged instead of committing.": "Ia ragu-ragu alih-alih tegas.",
  "Ask it to pick one and defend it: “Choose the single best option and say why the others lose.”": "Minta ia memilih satu dan membelanya: “Pilih satu opsi terbaik dan jelaskan kenapa yang lain kalah.”",
  "That's a generic answer — it could have been written without your details.": "Itu jawaban umum — bisa saja ditulis tanpa detail Anda.",
  "Give it your actual numbers and constraints, and ask it to redo the answer using only those.": "Berikan angka dan batasan Anda yang sebenarnya, lalu minta ia mengulang jawabannya hanya dengan itu.",
  "It spent the answer restating your question.": "Jawabannya habis untuk mengulang pertanyaan Anda.",
  "Tell it to skip the recap and start at the answer.": "Minta ia melewati rangkuman dan langsung menjawab.",
  "It looks cut off.": "Sepertinya terpotong.",
  "Ask it to continue from where it stopped, not to start again.": "Minta ia melanjutkan dari titik berhenti, bukan mulai dari awal.",
  "It asked you a question instead of answering.": "Ia malah bertanya alih-alih menjawab.",
  "Answer the question inside your next prompt so it can't stall again.": "Jawab pertanyaannya di prompt Anda berikutnya agar ia tidak tertahan lagi.",
  "This repeats an earlier answer — the conversation is going in circles.": "Ini mengulang jawaban sebelumnya — percakapannya berputar-putar.",
  "Change the angle: ask for what it would do differently, or give it a constraint it hasn't had.": "Ubah sudut pandang: tanyakan apa yang akan ia lakukan secara berbeda, atau beri batasan yang belum pernah ada.",
  "Sharpen": "Pertajam",
  "narrower and more specific — pin it down": "lebih sempit dan spesifik — pastikan",
  "Widen": "Perluas",
  "step back and ask for options you haven't considered": "mundur selangkah dan minta opsi yang belum Anda pertimbangkan",
  "Press": "Desak",
  "challenge the answer and make it defend or correct itself": "tantang jawabannya dan buat ia membela diri atau mengoreksi diri",
  "Reads clean structure well — tags mark where context ends and the task begins.": "Membaca struktur yang rapi dengan baik — tag menandai di mana konteks berakhir dan tugas dimulai.",
  "Turn on Extended Thinking for hard reasoning.": "Nyalakan Extended Thinking untuk penalaran yang sulit.",
  "Does best when you name the outcome and let it choose the path.": "Paling baik saat Anda menyebut hasilnya dan membiarkannya memilih jalannya.",
  "Let the router pick, or choose Thinking for complex tasks.": "Biarkan router memilih, atau pilih Thinking untuk tugas yang rumit.",
  "Wants direct, concise input and defaults to short answers.": "Butuh input yang langsung dan ringkas, dan cenderung menjawab pendek.",
  "Use Pro; enable Deep Research for multi-source work.": "Pakai Pro; aktifkan Deep Research untuk pekerjaan dengan banyak sumber.",
  "Handles direct, conversational prompts; ask for reasoning explicitly.": "Menangani prompt langsung dan santai; minta penalaran secara eksplisit.",
  "Turn on Think mode for step-by-step reasoning.": "Nyalakan mode Think untuk penalaran langkah demi langkah.",
  "Strong at structured reasoning and code.": "Kuat dalam penalaran terstruktur dan kode.",
  "Enable DeepThink (R1) for reasoning-heavy work.": "Aktifkan DeepThink (R1) untuk pekerjaan yang butuh banyak penalaran.",
  "Runs autonomously across many steps — give a goal, constraints, and a deliverable.": "Berjalan sendiri melalui banyak langkah — beri tujuan, batasan, dan hasil akhir.",
  "Give it files/links up front; let it run async.": "Berikan file/tautan di awal; biarkan ia berjalan di latar belakang.",
  "A search engine first — told which sources to trust and to cite them.": "Pada dasarnya mesin pencari — beri tahu sumber mana yang dipercaya dan minta ia mengutipnya.",
  "Pick Pro or Research mode; always check the citations.": "Pilih mode Pro atau Research; selalu periksa kutipannya.",
  "Only answers from your uploaded sources — cite passages, admit gaps.": "Hanya menjawab dari sumber yang Anda unggah — kutip bagiannya, akui kekurangannya.",
  "Upload sources first; try an Audio Overview.": "Unggah sumber dulu; coba Audio Overview.",
  "Wants a dense visual description plus parameters.": "Butuh deskripsi visual yang padat plus parameter.",
  "Append params like --ar 16:9 --style raw.": "Tambahkan parameter seperti --ar 16:9 --style raw.",
  "Separates a short style tag from the lyrics.": "Memisahkan tag gaya yang pendek dari lirik.",
