  "Summarise this in 3 bullets: ": "Ringkas ini dalam 3 poin: ",
  "What should I check on a used car before I buy it?": "Apa yang harus saya periksa pada mobil bekas sebelum membelinya?",
  "My period started this morning, medium flow": "Haid saya mulai pagi ini, aliran sedang",
  "Add it to your ledger in Money? You'll pick the account and confirm there.": "Tambahkan ke buku besar Anda di Uang? Anda akan memilih akun dan mengonfirmasinya di sana.",
  "Spotting": "Bercak",
  "Light": "Ringan",
  "Medium": "Sedang",
  "Heavy": "Deras",
  "item": "item",
  "items": "item",
  "15 questions a day": "15 pertanyaan sehari",
  "3 templates · 5 history items": "3 templat · 5 riwayat",
  "35B of knowledge, 3B doing the work on each token — near-frontier answers at a speed a laptop can sustain. A mixture-of-experts model keeps every expert in memory even though few run per token, so this needs the RAM of a 35B and the compute of a 3B.": "Pengetahuan 35B, 3B yang bekerja di setiap token — jawaban nyaris setara model terdepan dengan kecepatan yang sanggup dijalankan laptop. Model campuran pakar menyimpan semua pakar di memori meski hanya sedikit yang jalan per token, jadi butuh RAM 35B dan daya hitung 3B.",
  "A bigger length budget for reports, plans and analysis.": "Batas panjang yang lebih besar untuk laporan, rencana, dan analisis.",
  "Ask it as much as you like — no daily limit": "Tanya sepuasnya — tanpa batas harian",
  "Your phone reports {n} GB of memory": "Ponsel Anda melaporkan memori {n} GB",
  "Your computer reports {n} GB of memory": "Komputer Anda melaporkan memori {n} GB",
  "which is comfortable for everyday use": "yang nyaman untuk pemakaian sehari-hari",
  "which is enough, with shorter conversations": "yang cukup, dengan percakapan lebih pendek",
  ", ": ", ",
  "Documents, fleet records, copilot, every domain pack": "Dokumen, catatan armada, copilot, setiap paket bidang",
  "Small enough to download on mobile data if you need to.": "Cukup kecil untuk diunduh lewat data seluler bila perlu.",
  "This is a large model for a phone. It will run, and it will slow down noticeably once the phone gets warm — keep answers short, or pick the smaller one.": "Ini model besar untuk ponsel. Tetap jalan, tapi akan melambat jelas begitu ponsel menghangat — buat jawaban singkat, atau pilih yang lebih kecil.",
  "Every tool, and all 31 country packs": "Semua alat, dan seluruh 31 paket negara",
  "Finds what you promised people, from your own words": "Menemukan apa yang Anda janjikan kepada orang, dari kata-kata Anda sendiri",
  "Fixed randomness, so a workflow gives identical output every time it runs.": "Keacakan tetap, jadi alur kerja memberi hasil yang sama persis setiap dijalankan.",
  "Free web search: DuckDuckGo, Bing and Mojeek at once, then the top pages are read in full, so answers come from real passages.": "Pencarian web gratis: DuckDuckGo, Bing, dan Mojeek sekaligus, lalu halaman teratas dibaca utuh, sehingga jawaban berasal dari kutipan nyata.",
  "Free · no key": "Gratis · tanpa kunci",
  "Installing… {p}%": "Memasang… {p}%",
  "It remembers everything and can search it": "Mengingat semuanya dan bisa mencarinya",
  "Learns your vocabulary and writes the way you do": "Mempelajari kosakata Anda dan menulis seperti Anda",
  "No account, no sign-in, nothing uploaded": "Tanpa akun, tanpa masuk, tidak ada yang diunggah",
  "Running": "Berjalan",
  "Loading the model…": "Memuat model…",
  "Nothing in the app can reach the internet — no web lookup, no maps, no downloads. The model and everything on the phone keep working.": "Tidak ada yang di aplikasi bisa mengakses internet — tanpa pencarian web, peta, atau unduhan. Model dan semua yang ada di ponsel tetap berfungsi.",
  "The model reasons first on every question. Clearly better on hard problems, but on a phone the answer starts 30–90 s later. Off: tap “Think” on just the questions that need it.": "Model bernalar dulu di setiap pertanyaan. Jelas lebih baik untuk masalah sulit, tapi di ponsel jawaban baru mulai 30–90 dtk kemudian. Nonaktif: ketuk “Berpikir” hanya untuk pertanyaan yang memerlukannya.",
  "The same model as below, given the memory to hold a whole book of context at once. On a 48 GB machine the spare RAM is better spent on context than on precision — you can hand it an entire contract or a year of notes and it keeps all of it in view.": "Model yang sama seperti di bawah, dengan memori untuk menampung konteks sepanjang satu buku sekaligus. Di mesin 48 GB, sisa RAM lebih baik dipakai untuk konteks daripada presisi — Anda bisa memberinya seluruh kontrak atau catatan setahun dan semuanya tetap terjaga.",
  "The whole assistant, on your device": "Seluruh asisten, di perangkat Anda",
  "Works entirely offline. No account, ever.": "Berfungsi sepenuhnya offline. Tanpa akun, selamanya.",
