  "Notifications are off for Attune — tap to allow them, or reminders can't appear.": "Notifikasi Attune mati — ketuk untuk mengizinkan, atau pengingat tidak bisa muncul.",
  "Reminders may come up to 10 minutes late. Tap to allow “Alarms & reminders” for Attune so they ring on the minute.": "Pengingat bisa terlambat hingga 10 menit. Ketuk untuk mengizinkan “Alarm & pengingat” bagi Attune agar berbunyi tepat waktu.",
