  "MTP did not start on this phone, so this model runs without it.": "MTP tidak mulai di ponsel ini, jadi model ini berjalan tanpanya.",
  "MTP is off for this model.": "MTP nonaktif untuk model ini.",
  "This model has no MTP layers; install it again from the list to get them.": "Model ini tidak punya lapisan MTP; pasang ulang dari daftar untuk mendapatkannya.",
  "Not recommended: it was slower in our tests. Turn it off.": "Tidak disarankan: lebih lambat dalam uji kami. Matikan.",
  "Faster answers with a draft model": "Jawaban lebih cepat dengan model draf",
  "On: {d} guesses ahead, the main model checks.": "Aktif: {d} tebakan ke depan, model utama memeriksa.",
  "Qwen 3.5 0.8B guesses a few words ahead and the main model checks them in one go. Same answers, often faster writing.": "Qwen 3.5 0.8B menebak beberapa kata ke depan dan model utama memeriksanya sekaligus. Jawaban sama, sering kali menulis lebih cepat.",
  "Only works with a Qwen 3.5 model — the one in use is not.": "Hanya berfungsi dengan model Qwen 3.5 — yang sedang dipakai bukan.",
  "Download Qwen 3.5 0.8B as a helper (about 0.5 GB, once). Works with Qwen 3.5 models.": "Unduh Qwen 3.5 0.8B sebagai pembantu (sekitar 0,5 GB, sekali saja). Berfungsi dengan model Qwen 3.5.",
  "Downloading the draft model…": "Mengunduh model draf…",
