  "There is no readable text in this file.": "Tidak ada teks yang bisa dibaca di file ini.",
  "This answer could not be tied to a page — check the pages listed below before relying on it.": "Jawaban ini tidak bisa dikaitkan dengan halaman — periksa halaman yang tercantum di bawah sebelum mengandalkannya.",
  "Writing the answer…": "Menulis jawaban…",
  "{n} page reference(s) the AI made up were removed.": "{n} rujukan halaman karangan AI telah dihapus.",
  "{n} page(s) match": "{n} halaman cocok",
