  "Summarise this document": "Ringkas dokumen ini",
  "What are the key points?": "Apa poin-poin pentingnya?",
  "Checklist: what every answer must satisfy (one per line, optional)": "Daftar periksa: apa yang harus dipenuhi setiap jawaban (satu per baris, opsional)",
  "Facts the AI should know (prices, rules, terms — optional)": "Fakta yang perlu diketahui AI (harga, aturan, ketentuan — opsional)",
  "Separate topics with an empty line. Only the paragraphs that fit the question are used, so this can be long.": "Pisahkan topik dengan baris kosong. Hanya paragraf yang sesuai pertanyaan yang dipakai, jadi boleh panjang.",
  "Facts": "Fakta",
  "It also runs this small program on your phone (offline, in a locked box — no internet, no files, no access to the app)": "Ia juga menjalankan program kecil ini di ponsel Anda (offline, dalam kotak terkunci — tanpa internet, tanpa file, tanpa akses ke aplikasi)",
  "Edit or improve my CV": "Edit atau tingkatkan CV saya",
  "Say what to add or change («add my job at Dar Al Fouad Hospital as a nurse, 2019–2022», «change my phone to …»), or leave it empty and just make it more professional. You see the result before it is kept.": "Sebutkan apa yang ditambah atau diubah («tambahkan pekerjaan saya di Dar Al Fouad Hospital sebagai perawat, 2019–2022», «ubah nomor telepon saya menjadi …»), atau kosongkan dan buat lebih profesional saja. Anda melihat hasilnya sebelum disimpan.",
  "What should be added or changed? (optional)": "Apa yang perlu ditambah atau diubah? (opsional)",
  "Apply my change": "Terapkan perubahan saya",
  "Change + make it professional": "Ubah + buat profesional",
  "New version": "Versi baru",
  "Use this version": "Pakai versi ini",
  "Done — you can undo it": "Selesai — bisa dibatalkan",
  "Undo the last change": "Batalkan perubahan terakhir",
  "Stuck — starting again from scratch with a different approach": "Macet — mulai lagi dari awal dengan pendekatan lain",
  "Wrote it, with {n} tests.": "Sudah ditulis, dengan {n} tes.",
  "Your programs": "Program Anda",
  "not passing": "tidak lulus",
  "passing": "lulus",
  "✓ Passed all {n} tests.": "✓ Lulus semua {n} tes.",
  "✓ Ran without errors.": "✓ Berjalan tanpa error.",
  "The fix did not match the code.": "Perbaikan tidak cocok dengan kode.",
  "The model answered without code.": "Model menjawab tanpa kode.",
  "The fix deleted the tests — refused.": "Perbaikan menghapus tes — ditolak.",
  "The model answered without any code — try asking again in other words.": "Model menjawab tanpa kode apa pun — coba tanya lagi dengan kata lain.",
  "A picture — Studio draws it on this phone": "Sebuah gambar — Studio menggambarnya di ponsel ini",
  "Another version": "Versi lain",
  "Could not open that picture": "Tidak bisa membuka gambar itu",
  "Could not save": "Tidak bisa menyimpan",
  "Current photo quality in 4 steps: people, places, products and text in pictures. Also edits a photo you give it (“make it night”, “remove the car”).": "Kualitas foto terkini dalam 4 langkah: orang, tempat, produk, dan teks dalam gambar. Juga mengedit foto yang Anda berikan (“buat jadi malam”, “hapus mobilnya”).",
  "Describe the picture, in Arabic or English — e.g. “a felucca on the Nile at sunset”": "Deskripsikan gambarnya, dalam bahasa Arab atau Inggris — mis. “felucca di Sungai Nil saat matahari terbenam”",
  "Developing the picture…": "Mengembangkan gambar…",
  "Download it on Wi-Fi. After that, pictures are made with no internet at all.": "Unduh lewat Wi-Fi. Setelah itu, gambar dibuat tanpa internet sama sekali.",
  "Draw it": "Gambar",
  "Draw it in Studio": "Gambar di Studio",
  "A place — Maps finds it": "Sebuah tempat — Peta menemukannya",
  "Show on the map": "Tampilkan di peta",
  "Draw on the graphics chip (faster; switches itself off if the driver fails)": "Gambar di chip grafis (lebih cepat; mati sendiri jika driver gagal)",
  "Drawing on the GPU failed, so Attune switched Studio to the CPU. ": "Menggambar di GPU gagal, jadi Attune mengalihkan Studio ke CPU. ",
  "Drawing — step {n} of {t}": "Menggambar — langkah {n} dari {t}",
  "Each picture is made by a separate engine process: when it finishes, all its memory goes back to the phone. Nothing is uploaded.": "Setiap gambar dibuat oleh proses mesin terpisah: setelah selesai, seluruh memorinya kembali ke ponsel. Tidak ada yang diunggah.",
  "Edit a photo": "Edit foto",
  "Edit it": "Edit",
  "Edit this": "Edit ini",
  "GB, once": "GB, sekali saja",
