  "Makes a finished picture four times bigger and sharper — for printing or zooming in.": "Membuat gambar jadi empat kali lebih besar dan tajam — untuk dicetak atau diperbesar.",
  "Pick a photo": "Pilih foto",
  "Pick the photo to edit first.": "Pilih foto yang akan diedit dulu.",
  "Portrait": "Potret",
  "Quick draft": "Draf cepat",
  "Reading your description…": "Membaca deskripsi Anda…",
  "Save to gallery": "Simpan ke galeri",
  "Saved to {w}": "Disimpan ke {w}",
  "Saving to the gallery needs Android 10 or newer — use Share instead.": "Menyimpan ke galeri butuh Android 10 atau lebih baru — gunakan Bagikan.",
  "Saving…": "Menyimpan…",
  "Sharpening ×4": "Penajaman ×4",
  "Sharpening ×4 — part {n} of {t}": "Penajaman ×4 — bagian {n} dari {t}",
  "Square": "Persegi",
  "Starting the download…": "Memulai unduhan…",
  "Starting the picture engine…": "Memulai mesin gambar…",
  "Studio works in the Android app.": "Studio berfungsi di aplikasi Android.",
  "The chat model was paused to make room, and is loading again.": "Model obrolan dijeda untuk memberi ruang, dan sedang dimuat lagi.",
  "This APK has no picture engine yet — it comes with the next APK built on GitHub.": "APK ini belum punya mesin gambar — hadir di APK berikutnya yang dibuat di GitHub.",
  "This build draws on the CPU.": "Build ini menggambar di CPU.",
  "This build of the app has no picture engine yet.": "Build aplikasi ini belum punya mesin gambar.",
  "This phone has {n} GB — it may be too little for pictures.": "Ponsel ini punya {n} GB — mungkin kurang untuk gambar.",
  "This version of Attune has no graphics-chip picture engine, so pictures are drawn on the CPU (slower). An update adds it.": "Attune versi ini tidak punya mesin gambar chip grafis, jadi gambar dibuat di CPU (lebih lambat). Pembaruan akan menambahkannya.",
  "The picture engine stopped responding while loading the model, so it was stopped. Engine → Engine log shows its last lines — send them to support.": "Mesin gambar berhenti merespons saat memuat model, jadi dihentikan. Mesin → Log mesin menampilkan baris terakhirnya — kirim ke dukungan.",
  "This phone's GPU driver did not answer, so pictures are drawn on the CPU (slower).": "Driver GPU ponsel ini tidak menjawab, jadi gambar dibuat di CPU (lebih lambat).",
  "What should change? e.g. “make it night, with the street lights on”": "Apa yang perlu diubah? mis. “buat jadi malam, lampu jalan menyala”",
