  "None yet — add a field of type “Link to another table”, or ask below: “connect Jobs to Customers”.": "Belum ada — tambahkan kolom berjenis “Tautan ke tabel lain”, atau minta di bawah: “hubungkan Pekerjaan ke Pelanggan”.",
