  "No forms yet. A form shows only the fields you need, in your order, with ready values — pick it when you add a record.": "Belum ada formulir. Formulir hanya menampilkan kolom yang Anda perlukan, sesuai urutan Anda, dengan nilai siap — pilih saat menambah catatan.",
