  "That file isn't an app made with Attune Business.": "File itu bukan aplikasi yang dibuat dengan Attune Business.",
  "Updated from the app file — {n} tables with their records": "Diperbarui dari file aplikasi — {n} tabel beserta catatannya",
  "Opened — {n} tables with their records": "Dibuka — {n} tabel beserta catatannya",
  "Change the design in words — add fields to any table, new tables, links…": "Ubah rancangan dengan kata-kata — tambah kolom ke tabel mana pun, tabel baru, tautan…",
  "e.g. add Email and Tax ID to Suppliers, and a Warranty months field to Parts": "mis. tambahkan Email dan NPWP ke Pemasok, dan kolom Bulan garansi ke Suku cadang",
  "Saved — send this file; it opens in any browser, no Attune needed": "Tersimpan — kirim file ini; terbuka di peramban apa pun, tanpa Attune",
  "Excel files need Python, which isn't in this build — use CSV.": "File Excel butuh Python, yang tidak ada di build ini — pakai CSV.",
  "Making the Excel file…": "Membuat file Excel…",
  "Couldn't make the Excel file: {e}": "Tidak bisa membuat file Excel: {e}",
  "Give it to your team as an app: one file with all the data inside — it opens in any phone or computer browser, no Attune needed. When something needs changing, open the file here (Business → Open an app file), ask the AI, and send the new app back.": "Berikan ke tim Anda sebagai aplikasi: satu file berisi semua data — terbuka di peramban ponsel atau komputer mana pun, tanpa Attune. Saat ada yang perlu diubah, buka file di sini (Bisnis → Buka file aplikasi), minta AI, lalu kirim aplikasi barunya.",
  "Export as an app": "Ekspor sebagai aplikasi",
  "Excel workbook (all tables)": "Buku kerja Excel (semua tabel)",
  "The picture engine stopped before the picture was finished — Android may have closed it to free memory. Try “Quick draft”, or close other apps and try again.": "Mesin gambar berhenti sebelum gambar selesai — Android mungkin menutupnya untuk membebaskan memori. Coba “Draf cepat”, atau tutup aplikasi lain dan coba lagi.",
  "The picture could not be made. Open Engine → Engine log and send me what it says.": "Gambar tidak bisa dibuat. Buka Mesin → Log mesin dan kirimkan isinya kepada saya.",
  "Multi-token prediction (faster writing)": "Prediksi multi-token (menulis lebih cepat)",
  "Off by default: on some phones it doubles words and digits (“ItIt is is”, “20205”). Turn it on only if answers stay correct.": "Mati secara default: di beberapa ponsel kata dan angka jadi ganda (“ItIt is is”, “20205”). Aktifkan hanya jika jawaban tetap benar.",
  "The last picture didn't finish:": "Gambar terakhir tidak selesai:",
