  "Studio Turbo": "Studio Turbo",
  "Studio Pro": "Studio Pro",
  "Studio Pro HD": "Studio Pro HD",
  "Turbo · about 1 min": "Turbo · sekitar 1 mnt",
  "Studio Turbo+": "Studio Turbo+",
  "Recommended for your phone": "Disarankan untuk ponsel Anda",
  "Studio Ultra": "Studio Ultra",
  "Ultra · best quality, slow · {s} GB": "Ultra · kualitas terbaik, lambat · {s} GB",
  "best quality, slow": "kualitas terbaik, lambat",
  "fastest pictures": "gambar tercepat",
  "a graphics card with 8 GB or more: the most capable model": "kartu grafis 8 GB atau lebih: model paling mumpuni",
  "The most capable model: text inside pictures, busy scenes, people. Slow on a phone (about 10 minutes a picture), fast on a computer with a graphics card. Needs 12 GB RAM.": "Model paling mumpuni: teks di dalam gambar, adegan ramai, orang. Lambat di ponsel (sekitar 10 menit per gambar), cepat di komputer dengan kartu grafis. Butuh RAM 12 GB.",
  "about {s} s a picture": "sekitar {s} dtk per gambar",
  "8 GB or more and fast cores: the sharper XL model in one step": "8 GB atau lebih dan inti cepat: model XL yang lebih tajam dalam satu langkah",
  "not enough free storage or speed for the XL model": "penyimpanan kosong atau kecepatan tidak cukup untuk model XL",
  "the fast model fits this phone's memory": "model cepat muat di memori ponsel ini",
  "little memory or slow cores: smaller pictures, still clear": "memori sedikit atau inti lambat: gambar lebih kecil, tetap jelas",
  "Turbo+ · about 20 s · {s} GB": "Turbo+ · sekitar 20 dtk · {s} GB",
  "Faster and sharper than Turbo, with a better match to what you ask for: about 20 seconds a picture on the CPU. 512 px. For phones with 8 GB RAM or more.": "Lebih cepat dan tajam dari Turbo, lebih sesuai dengan permintaan Anda: sekitar 20 detik per gambar di CPU. 512 px. Untuk ponsel dengan RAM 8 GB atau lebih.",
  "Pro · best quality": "Pro · kualitas terbaik",
  "Pro on this phone's CPU: 10–20 min a picture": "Pro di CPU ponsel ini: 10–20 mnt per gambar",
  "This phone's graphics chip isn't working with Studio, so the Pro model would take 10–20 minutes a picture on the CPU. Studio Turbo makes a picture in about a minute.": "Chip grafis ponsel ini tidak bekerja dengan Studio, jadi model Pro butuh 10–20 menit per gambar di CPU. Studio Turbo membuat gambar sekitar semenit.",
  "Fast pictures on any phone: about a minute without a graphics chip, seconds with one. 512 px — great for ideas, drafts and posts.": "Gambar cepat di ponsel mana pun: sekitar semenit tanpa chip grafis, hitungan detik dengan chip grafis. 512 px — pas untuk ide, draf, dan postingan.",
  "The best photo quality: people, places, products and text in pictures, 1024 px. Also edits a photo you give it (“make it night”, “remove the car”). Needs a working graphics chip — on the CPU a picture takes 10–20 minutes.": "Kualitas foto terbaik: orang, tempat, produk, dan teks dalam gambar, 1024 px. Juga mengedit foto yang Anda berikan (“buat jadi malam”, “hapus mobilnya”). Butuh chip grafis yang berfungsi — di CPU satu gambar butuh 10–20 menit.",
  "Studio Pro at full precision: finer detail, cleaner faces, hands and text. Also edits your photos by instruction. Needs a working graphics chip and 12 GB RAM.": "Studio Pro dengan presisi penuh: detail lebih halus, wajah, tangan, dan teks lebih bersih. Juga mengedit foto Anda lewat instruksi. Butuh chip grafis yang berfungsi dan RAM 12 GB.",
  "Still working — nothing is stuck. Turbo takes about 1–2 minutes on the CPU. Keep Attune open; Stop cancels it.": "Masih bekerja — tidak ada yang macet. Turbo butuh sekitar 1–2 menit di CPU. Biarkan Attune terbuka; Berhenti membatalkannya.",
  "Still working — nothing is stuck. Without the graphics chip a Pro picture takes 10–20 minutes (edits take longer). For speed, pick Turbo. Keep Attune open; Stop cancels it.": "Masih bekerja — tidak ada yang macet. Tanpa chip grafis, gambar Pro butuh 10–20 menit (edit lebih lama). Untuk kecepatan, pilih Turbo. Biarkan Attune terbuka; Berhenti membatalkannya.",
  "Delete this chat?": "Hapus obrolan ini?",
  "This can't be undone.": "Ini tidak bisa dibatalkan.",
  "Delete this reminder?": "Hapus pengingat ini?",
  "Delete this project?": "Hapus proyek ini?",
  "Remove this crane from the fleet?": "Keluarkan derek ini dari armada?",
  "Remove this from the project?": "Keluarkan ini dari proyek?",
  "Delete this picture?": "Hapus gambar ini?",
  "Delete this place?": "Hapus tempat ini?",
  "Forget this correction?": "Lupakan koreksi ini?",
  "Forget": "Lupakan",
  "Delete this action?": "Hapus tindakan ini?",
  "Spark (helper)": "Spark (pembantu)",
  "Only works with Spark, Glow, Core and Zenith — not with the model in use.": "Hanya berfungsi dengan Spark, Glow, Core, dan Zenith — bukan dengan model yang sedang dipakai.",
  "Download Spark as a helper (about 0.5 GB, once). Works with Glow, Core and Zenith.": "Unduh Spark sebagai pembantu (sekitar 0,5 GB, sekali saja). Berfungsi dengan Glow, Core, dan Zenith.",
  "This is a big model for a phone — Core is about 2–3× faster.": "Ini model besar untuk ponsel — Core sekitar 2–3× lebih cepat.",
  "The strongest model a 12 GB phone can run: expert answers, and the best at reading documents and photos.": "Model terkuat yang bisa dijalankan ponsel 12 GB: jawaban sekelas pakar, dan terbaik dalam membaca dokumen dan foto.",
  "Core made 10% smaller for a 4 GB phone — worth it over Glow.": "Core yang diperkecil 10% untuk ponsel 4 GB — lebih baik daripada Glow.",
  "Runs on a budget phone and still reads photos. Good short answers; long reasoning shows its size.": "Berjalan di ponsel murah dan tetap membaca foto. Jawaban singkat bagus; penalaran panjang terlihat keterbatasannya.",
  "For a phone that can't hold anything else: tidying and shortening text. Not for reasoning.": "Untuk ponsel yang tak sanggup menampung yang lain: merapikan dan meringkas teks. Bukan untuk penalaran.",
  "The biggest speed-up on this phone is the fast engine: Blaze on the graphics chip — first words in about a second. Tap “Switch to the fast engine” above.": "Percepatan terbesar di ponsel ini adalah mesin cepat: Blaze di chip grafis — kata pertama sekitar satu detik. Ketuk “Beralih ke mesin cepat” di atas.",
