  "Pay with InstaPay, Vodafone Cash or a card, and send this code with it. You'll get your activation code back, made for this phone.": "Bayar dengan InstaPay, Vodafone Cash, atau kartu, dan kirim kode ini bersamanya. Anda akan mendapat kode aktivasi yang dibuat khusus untuk ponsel ini.",
  "Your request code": "Kode permintaan Anda",
