  "Pro is active on this phone. Thank you for supporting Attune!": "Pro aktif di ponsel ini. Terima kasih telah mendukung Attune!",
  "Your free Pro trial: {n} days left — everything is unlocked. Keep it by choosing a plan.": "Uji coba Pro gratis Anda: sisa {n} hari — semuanya terbuka. Pertahankan dengan memilih paket.",
  "Free gives you {n} answers a day on every model. Pro removes every limit:": "Paket gratis memberi Anda {n} jawaban sehari di setiap model. Pro menghapus semua batas:",
  "Unlimited answers — no daily limit": "Jawaban tanpa batas — tanpa batas harian",
