  "Everything runs on your phone: no account, nothing uploaded. Your plan is checked on the phone, even offline.": "Semuanya berjalan di ponsel Anda: tanpa akun, tidak ada yang diunggah. Paket Anda diperiksa di ponsel, bahkan saat offline.",
  "Your Pro plan has ended — renew it any time in Plan.": "Paket Pro Anda telah berakhir — perbarui kapan saja di Paket.",
