  "Put the ask after the data (Gemini/GPT guidance)": "Taruh permintaan setelah data (panduan Gemini/GPT)",
  "Define the output shape explicitly": "Tentukan bentuk hasil secara eksplisit",
  "Name the goal so the model reasons toward it": "Sebut tujuannya agar model bernalar ke arah itu",
  "Specificity → fewer misinterpretations": "Lebih spesifik → lebih sedikit salah tafsir",
  "Goal-framing beats tone adjectives alone": "Menyebut tujuan lebih baik daripada sekadar kata sifat nada",
  "Data first, question last improves grounding": "Data dulu, pertanyaan terakhir memperbaiki keterpaduan",
  "Role-free outcome framing (2026 guidance)": "Pembingkaian hasil tanpa peran (panduan 2026)",
  "Explicit output shape reduces rework": "Bentuk hasil yang eksplisit mengurangi pengerjaan ulang",
  "Goal + constraint framing produces usable scripts": "Pembingkaian tujuan + batasan menghasilkan skrip yang berguna",
  "Stated criteria prevent generic pro/con lists": "Kriteria yang disebut mencegah daftar pro/kontra yang generik",
  "Concrete constraints beat generic advice": "Batasan konkret mengalahkan saran generik",
  "Time constraints force actionable plans": "Batasan waktu memaksa rencana yang bisa dijalankan",
  "Matching to the posting outperforms templates": "Menyesuaikan dengan lowongan lebih unggul daripada templat",
  "Role-specific prompting beats generic question lists": "Prompt khusus peran lebih baik daripada daftar pertanyaan generik",
  "Source-anchored prompts reduce invented detail": "Prompt berpatokan sumber mengurangi detail karangan",
  "Constraints up front prevent generic travel advice": "Batasan di awal mencegah saran perjalanan yang generik",
  "Explaining the 'why' improves targeting (Anthropic)": "Menjelaskan 'mengapa' memperbaiki sasaran (Anthropic)",
  "Search tools need source + recency constraints": "Alat pencarian butuh batasan sumber + keterbaruan",
  "Constraints up front prevent generic answers": "Batasan di awal mencegah jawaban generik",
  "Active recall outperforms re-reading": "Mengingat aktif mengalahkan membaca ulang",
  "Sectioned output aids comprehension": "Hasil berbagian membantu pemahaman",
  "Explicit critique requests beat 'what do you think'": "Permintaan kritik yang eksplisit lebih baik daripada 'bagaimana menurutmu'",
  "Naming review axes prevents shallow feedback": "Menyebut sumbu tinjauan mencegah umpan balik dangkal",
  "Include context + attempted fixes for accuracy": "Sertakan konteks + perbaikan yang sudah dicoba demi akurasi",
  "Section-by-section output beats 'write a page'": "Hasil per bagian lebih baik daripada 'tulis satu halaman'",
  "Persona-specific prompts improve targeting": "Prompt khusus persona memperbaiki sasaran",
  "Stating criteria prevents generic pro/con lists": "Menyebut kriteria mencegah daftar pro/kontra yang generik",
  "Level-setting improves explanation fit": "Menentukan tingkat memperbaiki kecocokan penjelasan",
  "Specifying length prevents rambling summaries": "Menentukan panjang mencegah ringkasan bertele-tele",
  "Ask to implement, not 'suggest changes' (Anthropic)": "Minta untuk mengimplementasikan, bukan 'menyarankan perubahan' (Anthropic)",
  "Reasoning models excel with clear scope, no examples": "Model penalaran unggul dengan cakupan jelas, tanpa contoh",
  "Name every state so nothing is left ambiguous": "Sebut setiap kondisi agar tidak ada yang ambigu",
  "Natural language + explicit variety works on GPT": "Bahasa alami + variasi eksplisit bekerja di GPT",
  "Outcome framing beats feature lists": "Pembingkaian hasil mengalahkan daftar fitur",
  "Gemini prefers direct, constrained prompts": "Gemini lebih suka prompt langsung dan terbatas",
  "Short + specific tone yields natural output": "Nada singkat + spesifik menghasilkan hasil yang natural",
  "Chain-of-thought: +~40% avg on hard reasoning (Wei et al.); MultiArith 18%→79%. Skip on reasoning models — minimal gain, more latency.": "Chain-of-thought: rata-rata +~40% pada penalaran sulit (Wei dkk.); MultiArith 18%→79%. Lewati pada model penalaran — keuntungan minim, latensi lebih tinggi.",
  "1–5 examples (few-shot) raise pattern-task accuracy up to +43%; best on non-reasoning models like Gemini. Don't add examples for pure reasoning tasks — can hurt.": "1–5 contoh (few-shot) menaikkan akurasi tugas pola hingga +43%; terbaik pada model non-penalaran seperti Gemini. Jangan tambahkan contoh untuk tugas penalaran murni — bisa merugikan.",
  "OpenAI/Anthropic 2026: describe what a good result looks like; over-instructing adds noise on modern models.": "OpenAI/Anthropic 2026: jelaskan seperti apa hasil yang baik; instruksi berlebihan menambah derau pada model modern.",
  "2026 practice: set how hard to think (thinking/effort control) and spend words on the outcome, not on 'think step by step'.": "Praktik 2026: atur seberapa keras berpikir (kontrol berpikir/usaha) dan gunakan kata untuk hasil, bukan 'berpikir langkah demi langkah'.",
  "Clarification-first reduces wasted turns — the model gathers missing context instead of guessing.": "Klarifikasi dulu mengurangi putaran sia-sia — model mengumpulkan konteks yang kurang alih-alih menebak.",
  "Outcome criteria (what 'good' means) outperform process instructions on 2026 models.": "Kriteria hasil (arti 'baik') mengalahkan instruksi proses pada model 2026.",
  "Verification steps reduce errors on factual/analytical tasks.": "Langkah verifikasi mengurangi kesalahan pada tugas faktual/analitis.",
  "Explicit sections prevent rambling updates": "Bagian yang eksplisit mencegah pembaruan bertele-tele",
  "Asking for risks surfaces what you forgot": "Meminta risiko memunculkan hal yang terlupa",
  "Outcome framing keeps feedback constructive": "Pembingkaian hasil menjaga umpan balik tetap membangun",
  "Explicit audience prevents vague procedures": "Audiens yang eksplisit mencegah prosedur kabur",
  "Spaced repetition beats massed practice": "Pengulangan berjarak mengalahkan latihan menumpuk",
  "Worked examples aid transfer to new problems": "Contoh soal membantu menerapkan ke masalah baru",
  "Planning prompts reduce rework on complex tasks": "Prompt perencanaan mengurangi pengerjaan ulang pada tugas kompleks",
  "Explicitly requesting edge cases improves coverage": "Meminta kasus tepi secara eksplisit memperluas cakupan",
  "Specificity outperforms enthusiasm in cold outreach": "Kespesifikan mengalahkan antusiasme dalam penjangkauan dingin",
  "Goal-anchored planning beats idea dumps": "Perencanaan berpatokan tujuan mengalahkan tumpukan ide",
  "Requesting alternatives counters fixation": "Meminta alternatif melawan kekakuan pikiran",
  "Citation requirements reduce unsupported claims": "Kewajiban kutipan mengurangi klaim tanpa dasar",
