  "Reading your {f} conversation…": "Membaca percakapan {f} Anda…",
  "Reading the conversation…": "Membaca percakapan…",
  "Shared links are opened in the Android app — or paste the conversation's text here.": "Tautan bagikan dibuka di aplikasi Android — atau tempel teks percakapannya di sini.",
  "I read your conversation with {f}{t} (about {n} words). Ask me anything about it — check it, summarise it, or carry on from where it stopped.": "Saya sudah membaca percakapan Anda dengan {f}{t} (sekitar {n} kata). Tanyakan apa saja tentangnya — periksa, ringkas, atau lanjutkan dari tempat berhenti.",
  "Attune · the AI runs on your device · no account, no sign-in · web lookup only when a question needs it (Auto) — switch it off with the Web button": "Attune · AI berjalan di perangkat Anda · tanpa akun, tanpa masuk · pencarian web hanya saat pertanyaan memerlukannya (Otomatis) — matikan dengan tombol Web",
  "Web: Off — nothing is looked up": "Web: Mati — tidak ada yang dicari",
  "While Web is off in Chat, questions about prices, specs, news, scores or this year are still looked up (only the search words leave the phone). Off: nothing is looked up unless you turn Web on.": "Saat Web mati di Obrolan, pertanyaan tentang harga, spesifikasi, berita, skor, atau tahun ini tetap dicari (hanya kata pencariannya yang keluar dari ponsel). Mati: tidak ada yang dicari kecuali Anda menyalakan Web.",
  "The model wrote nonsense — restarting it in safe mode and asking again…": "Model menulis tak karuan — memulai ulang dalam mode aman dan bertanya lagi…",
  "This model writes nonsense on this phone, even in safe mode. Pick another model in Engine (Core works well) and tell us which one failed.": "Model ini menulis tak karuan di ponsel ini, bahkan dalam mode aman. Pilih model lain di Mesin (Core bagus) dan beri tahu kami yang mana yang gagal.",
  "Safe mode is on for this model: it once wrote nonsense on this phone, so it runs without speed tricks and with full-precision memory (a little slower, same answers).": "Mode aman aktif untuk model ini: pernah menulis tak karuan di ponsel ini, jadi berjalan tanpa trik kecepatan dan dengan memori presisi penuh (sedikit lebih lambat, jawaban sama).",
  "Turn safe mode off": "Matikan mode aman",
  "Or any topic you like": "Atau topik apa pun yang Anda suka",
  "I can answer about your next period, being late, ovulation, the fertile window, cycle and period length, your history and symptoms.": "Saya bisa menjawab soal haid berikutnya, keterlambatan, ovulasi, masa subur, panjang siklus dan haid, riwayat, dan gejala Anda.",
